const D = { energy: .6, scale: 1, density: .5, speed: 1, wind: .5, hue: 210, x: .5, y: .78, style: 'concrete', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Hyperboloid power-station cooling towers on a lower band, each billowing a plume of
// steam that rises, drifts and dissipates for ever. A SET: towers sit low and the steam
// climbs into open frame; alpha scales every mark. New family. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, en = cl(P.energy,0,1), dn = cl(P.density,0,1), wnd = cl(P.wind,0,1);
const HU = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', dusk = sty==='dusk', therm = sty==='thermal', eng = sty==='engraving';
const AL = cl(P.alpha,0,100);
if (AL > 0.5) {

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const light = (.5+.5*en)*(.55+.5*K.intensity) + bass*.22;
// sky light direction drifts -> the steam's lit side shifts (incommensurate)
const skyA = 0.7*Math.sin(tt*.05*P.speed) + 0.35*Math.sin(tt*.11+1.1);

// ---- soft cloud sprite, built once (billowy blob via layered noise falloff) ----
if (!S.cloud){ const G=createGraphics(80,80); G.pixelDensity(1); G.loadPixels();
  const nz=(x,y)=>{ const s=Math.sin(x*12.9+y*78.2)*43758.5; return s-Math.floor(s); };
  for(let y=0;y<80;y++)for(let x=0;x<80;x++){ const dx=(x-40)/40,dy=(y-40)/40; const d=Math.sqrt(dx*dx+dy*dy);
    let a=Math.pow(cl(1-d,0,1),1.7); a*= .7+.6*nz(Math.floor(x/7),Math.floor(y/7)); a=cl(a,0,1)*255;
    const o=4*(y*80+x); G.pixels[o]=255;G.pixels[o+1]=255;G.pixels[o+2]=255;G.pixels[o+3]=a; }
  G.updatePixels(); S.cloud=G; }

function towerCol(v){ if (bp) return [200,55,cl(10+v*10,6,28)]; if (eng) return [34,6,cl(10+v*70,6,90)];
  if (therm) return [cl(220-v*180,0,300),70,cl(20+v*60,8,90)];
  if (dusk) return [cl(HU+16,0,360),cl(30-v*20,4,44),cl(6+v*44,3,60)];
  return [cl(HU-2,0,360),cl(10,2,16),cl(24+v*40,8,74)]; }        // weathered concrete
function setF(c,a){ fill(c[0],c[1],c[2],a*AL/100); }
function setS(c,a){ stroke(c[0],c[1],c[2],a*AL/100); }

const baseY = cl(P.y,.45,.92)*height;
const sc = cl(P.scale,.3,2.4);
const nT = 2 + Math.round(dn*2);                            // 2..4 towers
const cx = cl(P.x,.06,.94)*width;

// hyperboloid radius profile
function rprof(v, rBot){ const rTh=rBot*0.60, rTop=rBot*0.70, vTh=0.72;
  if (v<vTh){ const t=v/vTh; return rTh + (rBot-rTh)*Math.pow(1-t,1.6); }
  const t=(v-vTh)/(1-vTh); return rTh + (rTop-rTh)*Math.pow(t,1.25); }

// depth-sort: far towers first
const info=[];
for (let i=0;i<nT;i++){ const dep=fr(i*5.3); info.push({i,dep}); }
info.sort((a,b)=>a.dep-b.dep);

for (const T of info){
  const i=T.i, dep=T.dep;
  const H = u*(0.34+dep*0.30)*sc;
  const rBot = H*0.34;
  const tx = cx + (i-(nT-1)/2)*rBot*3.0 + (fr(i*3.7)-.5)*rBot*0.6;
  const ty = baseY - (1-dep)*u*0.04;                        // far towers a touch back/up
  const dim = 0.6+dep*0.4;
  const NV = 22;
  // ---- tower shell (hyperboloid silhouette), shaded across its round + banding ----
  push();
  const litX = skyA;                                        // -1..1 which side is lit
  noStroke();
  // draw as vertical strips so we can shade the round body and add lift-line banding
  const NSX=9;
  for (let s2=0;s2<NSX;s2++){
    const fx0=-1+2*s2/NSX, fx1=-1+2*(s2+1)/NSX, fxm=(fx0+fx1)*.5;
    const cyl = cl(Math.cos((fxm-litX*0.5)*1.3),0,1);       // round-body shading
    const v = cl((0.30+0.6*cyl)*light,0,1.05);
    setF(towerCol(v), (dusk?86:90)*dim);
    beginShape();
    for (let k=0;k<=NV;k++){ const vv=k/NV; const rr=rprof(vv,rBot); vertex(tx+fxm*rr, ty-vv*H); }
    for (let k=NV;k>=0;k--){ const vv=k/NV; const rr=rprof(vv,rBot); vertex(tx+fx1*rr, ty-vv*H); }
    endShape(CLOSE);
  }
  // horizontal construction lift-lines (banding texture)
  setS(towerCol(0.15),40*dim); strokeWeight(Math.max(1,u*.0008)); noFill();
  for (let k=1;k<NV;k++){ const vv=k/NV; const rr=rprof(vv,rBot);
    beginShape(); for(let m=0;m<=10;m++){ const fxm=-1+2*m/10; vertex(tx+fxm*rr, ty-vv*H - Math.abs(fxm)*rr*0.04); } endShape(); }
  // vertical weather staining
  setS(towerCol(0.08),26*dim); strokeWeight(Math.max(1,u*.0009));
  for (let ss=0;ss<7;ss++){ const fxm=(fr(i*11+ss)*2-1)*0.9; const rrT=rprof(0.95,rBot), rrB=rprof(0.05,rBot);
    line(tx+fxm*rrT, ty-0.95*H, tx+fxm*rrB, ty-0.05*H); }
  // rim highlight at the top mouth
  setS(towerCol(cl(0.5+light*.4,0,1)), 60*dim); strokeWeight(Math.max(1,u*.0016)); noFill();
  const rT=rprof(1,rBot); beginShape(); for(let m=0;m<=16;m++){ const an=Math.PI*m/16; vertex(tx-Math.cos(an)*rT, ty-H+Math.sin(an)*rT*0.12); } endShape();
  ellipse(tx, ty-H, rT*2, rT*0.24);
  // A-frame air-intake legs at the base (gaps = air in)
  setF(towerCol(0.05), 88*dim); noStroke();
  const rB=rprof(0.02,rBot);
  for (let lg=0; lg<10; lg++){ const a0=lg/10, a1=(lg+0.55)/10; const x0=tx-rB+2*rB*a0, x1=tx-rB+2*rB*a1;
    quad(x0, ty, x1, ty, x1*0.98+tx*0.02, ty-H*0.06, x0*0.98+tx*0.02, ty-H*0.06); }
  pop();

  // ---- the steam plume: soft blobs rising, drifting, dissipating for ever ----
  const throatY = ty - H*0.98, throatR = rprof(1,rBot);
  const plumeH = H*(1.1+0.7*wnd);
  const NB = 10 + Math.round(dn*8);
  push();
  for (let j=0;j<NB;j++){
    const off=fr(i*17+j*3.7), rate=0.045+0.075*fr(i*5+j*2.1);
    const p=((tt*rate*P.speed + off)%1+1)%1;                // 0 fresh .. 1 gone
    const rise=Math.pow(p,0.82);
    const by=throatY - rise*plumeH;
    const windX=(wnd*u*0.14)*(rise*rise)*(0.6+0.8*Math.sin(tt*.07+i));
    const turb=Math.sin(tt*(0.25+fr(j)*0.4)+j*1.7)*u*0.02*rise;
    const bx=tx + windX + turb + (fr(i*7+j)-.5)*throatR*1.4;
    const size=throatR*(0.9 + rise*2.6)*(0.7+0.5*fr(j*3.1));
    const af=Math.pow(Math.sin(p*Math.PI),0.7);             // fade in and out
    // lit side of the steam brighter; dusk underlights it warm near the base
    const litSide=cl(0.5+litX*0.4,0,1);
    let sb = cl((dusk? (0.28+(1-rise)*0.5) : 0.72) * (0.5+0.7*light) * litSide, 0, 1);
    let sh = dusk ? (HU+18) : (bp?200: (therm? cl(40-rise*40,0,300):HU));
    let ss = dusk ? cl(30*(1-rise)+6,0,50) : (bp?40: (therm?60:6));
    push(); blendMode(BLEND);
    tint(sh, ss, cl(sb*100,4,100), cl(af*(bp?12:34)*en*1.4+af*10,0,72)*AL/100);
    image(S.cloud, bx-size, by-size, size*2, size*2);
    noTint(); pop();
    // a brighter lit core near the plume base (ADD, small)
    if (!bp && rise<0.5){ push(); blendMode(ADD); noStroke();
      tint(dusk?(HU+22):sh, dusk?36:8, 100, cl(af*(1-rise*2)*22*light,0,40)*AL/100);
      image(S.cloud, bx-size*.6, by-size*.6, size*1.2, size*1.2); noTint(); pop(); }
  }
  pop();
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0; strokeWeight(1);
}
